  /* --- a tower: facade walls, a parapet, a rooftop, sometimes neon ------------------ */
  function buildTower(x, z, w, d, blockX, blockZ, nearHarbor, ix, iz) {
    const dist = Math.hypot(x, z) / HALF;
    const central = Math.max(0, 1 - dist);
