      trim.plate(x, podiumH + 0.02, z, w - 0.5, d - 0.5, 0, tint(0x2a2632));
      const shrink = 0.62 + random() * 0.18;
      tw = w * shrink;
      td = d * shrink;
      tx = x + (random() - 0.5) * (w - tw) * 0.2;
      tz = z + (random() - 0.5) * (d - td) * 0.2;
