    trim.box(tx, roofY - 0.1, tz + td / 2 - t / 2, tw, 1.1, t, tint(TRIM_COLOR).multiplyScalar(0.9));
    trim.box(tx - tw / 2 + t / 2, roofY - 0.1, tz, t, 1.1, td, tint(TRIM_COLOR).multiplyScalar(0.9));
    trim.box(tx + tw / 2 - t / 2, roofY - 0.1, tz, t, 1.1, td, tint(TRIM_COLOR).multiplyScalar(0.9));
