    trim.box(x - w / 2 - 0.16, 0.02, z, 0.3, shopH, d * 0.96, tint(0x2e2b38));
    trim.box(x + w / 2 + 0.16, 0.02, z, 0.3, shopH, d * 0.96, tint(0x2e2b38));
