  /* --- pedestrians ---------------------------------------------------------------- */
  function spawnPed(x, z) {
    const scale = random.range(0.92, 1.06);
    const person = buildPerson(random.pick(SHIRTS), random.pick(PANTS), random.pick(SKIN), scale);
    group.add(person.group);
    const ped = {
      ...person,
      x, z,
      heading: random() * 6.28,
      speed: random.range(1.1, 1.8),
      walk: random() * 6.28,
      target: null,
      state: 'walk',
      panic: 0,
      alive: true,
      dead: 0,
