  gun.visible = false;

  const legBuild = new MeshBuilder();
  legBuild.part(0, -0.4, 0, 0.19, 0.8, 0.21, 0, new THREE.Color(PANTS));
  legBuild.part(0, -0.78, 0.04, 0.2, 0.1, 0.28, 0, new THREE.Color(0x14141c));
  const legGeo = legBuild.geometry();
