  let carModel = buildCar('muscle', 0x2fb3a6, { detailed: true });
  carModel.group.visible = false;
  scene.add(carModel.group);
  let carKind = 'muscle';
  let carColor = 0x2fb3a6;

  const state = {
    onFoot: true,
    x: 0, z: 0, y: 0,
    vy: 0,
    vx: 0, vz: 0,
    heading: 0,
    speed: 0,
    steer: 0,
    hp: 100,
    armor: 0,
    vehicle: null,
    wheelSpin: 0,
    walkPhase: 0,
    gunOut: false,
    recoil: 0,
    alive: true,
    skid: 0,
    inWater: false,
  };

  let yaw = 0;
  let pitch = 0.12;
  let camShake = 0;
  const camPos = new THREE.Vector3(0, 6, -8);
  const camLook = new THREE.Vector3();
  const tmpV = new THREE.Vector3();

  function spawn(x, z, heading = 0, inCar = false) {
    state.x = x;
    state.z = z;
    state.heading = heading;
    state.y = 0;
    state.vx = 0;
    state.vz = 0;
    state.vy = 0;
    state.speed = 0;
    state.alive = true;
    state.onFoot = !inCar;
    yaw = heading;
    pitch = 0.12;
    if (inCar) {
      carModel.group.visible = true;
      carModel.group.position.set(x, 0, z);
      carModel.group.rotation.y = heading;
      model.group.visible = false;
    } else {
      carModel.group.visible = false;
      model.group.visible = true;
      model.group.position.set(x, 0, z);
    }
    camPos.set(x - Math.sin(heading) * 7, 4, z - Math.cos(heading) * 7);
    camLook.set(x, 1.4, z);
