    for (let i = units.length - 1; i >= 0; i -= 1) {
      if (!units[i].alive && units[i].kind !== 'cop') units.splice(i, 1);
    }
  }

  return {
    state,
    units,
    update,
    crime,
    clear,
    hurtUnit,
    spawnCruiser,
    spawnCop,
    get wanted() {
      return state.wanted;
    },
    get stars() {
      return Math.min(WANTED.max, Math.ceil(state.wanted));
    },
  };
